import{_ as a,a0 as u,w as s,s as p,ao as x,I as r,x as i,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"微軟正在成為一個 Linux 供應商 | LCTT x X-CMD","titleTemplate":false,"description":"微軟正在成為一個 Linux 供應商 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"微軟正在成為一個 Linux 供應商 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"微軟正在成為一個 Linux 供應商 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170516 How Microsoft is becoming a Linux vendor","title":"微軟正在成為一個 Linux 供應商","tag":"201706","desc":""},"relativePath":"201706/20170516 How Microsoft is becoming a Linux vendor.md","filePath":"[post].md"}'),l={name:"201706/20170516 How Microsoft is becoming a Linux vendor.md"};function L(d,n,m,w,f,T){const o=u("Link");return s(),p("div",null,[n[13]||(n[13]=x('<h1 id="微軟正在成為一個-linux-供應商" tabindex="-1">微軟正在成為一個 Linux 供應商 <a class="header-anchor" href="#微軟正在成為一個-linux-供應商" aria-label="Permalink to “微軟正在成為一個 Linux 供應商”">​</a></h1><blockquote><p>微軟通過將 Linux 融入自己的產品中來彌合與 Linux 的裂隙。</p></blockquote><p><img src="http://images.techhive.com/images/article/2017/05/microsoft-100722875-large.jpg" alt=""></p><p>Linux 以及開源技術在數據中心、雲以及 IoT 中變得如此主流，以至於微軟無法忽視他們。</p><p>在微軟自己的雲中，三分之一的機器運行着 Linux。這些是運行 Linux 的微軟客户。微軟需要支持他們使用的平台，否則他們將到別處去了。</p><p>以下就是微軟如何將 Linux 戰略落實到它的開發者平台 （Windows 10）、雲 （Azure） 以及數據中心 （Windows Server） 上的。</p><p><strong>Windows 中的 Linux：</strong> IT 專家管理公共或者私有 Linux 機器需要原生的 UNIX 工具。Linux 以及 macOS 是僅有的二個提供原生能力的平台。這也難怪你在各種會議如 DockerCon、OpenStack Summit 或者 CoreOS Fest 看到的都是 MacBook 或者少量的 Linux 桌面。</p><p>為了彌補這之間的裂隙，微軟與 Canonical 協作在 Windows 內部構建了一個 Linux 子系統，它提供了原生的 Linux 工具。這是一個很棒的妥協，這樣 IT 專家可以在繼續使用 Windows 10 桌面的同時能夠使用大多數 Linux 工具來管理他們的 Linux 機器。</p><p><strong>Azure 中的 Linux：</strong> 不能完整支持 Linux 的雲有什麼好的呢？微軟一直以來與 Linux 供應商合作來使客户能夠在 Azure 中運行 Linux 程序以及任務。</p><p>微軟不僅與三家主要的 Linux 供應商 Red Hat、SUSE 和 Canonical 簽署了協議，還與無數的其他公司合作，為 Debian 這樣的基於社區的發行版提供了支持。</p><p><strong>Windows Server 中的 Linux：</strong> 這是剩下的最後一塊拼圖。客户使用的 Linux 容器是一個巨大的生態系統。Docker Hub 上有超過 90 萬個 Docker 容器，它們只能在 Linux 機器上運行。微軟希望把這些容器帶到自己的平台上。</p><p>在 DockerCon 中，微軟宣佈在 Windows Server 中支持 Linux 容器，將這些容器都帶到 Windows 中。</p><p>事情正變得更加有趣，在 Windows 10 上的 Bash on Ubuntu 成功之後，微軟正將 Ubuntu bash 帶到 Windows Server 中。是的，你聽的沒錯。Windows Server 也將會有一個 Linux 子系統。</p><p>微軟的高級項目經理 Rich Turne 告訴我：“服務器上的 WSL 為管理員提供了偏好的 *NIX 管理腳本和工具，以便讓他們可以在更熟悉的工作環境工作。”</p><p>微軟在一個通告中稱它將允許 IT 專家 “可以在 Windows Server 容器主機上使用在 Linux 容器上所用的相同的腳本、工具、流程和容器鏡像。這些容器使用我們的 Hyper-V 隔離技術結合你選擇的 Linux 內核來託管負載，而主機上的管理腳本以及工具使用 WSL。”</p><p>在覆蓋了上面三個情況後，微軟已經成功地創建了一個客户不必選擇任何 Linux 供應商的環境。</p><h3 id="它對微軟意味着什麼" tabindex="-1">它對微軟意味着什麼？ <a class="header-anchor" href="#它對微軟意味着什麼" aria-label="Permalink to “它對微軟意味着什麼？”">​</a></h3><p>通過將 Linux 融入它自己的產品，微軟已經成為了一個 Linux 供應商。它是 Linux 基金會的一份子，它是眾多 Linux 貢獻者之一，並且它現在在自己的商店中分發 Linux。</p><p>只有一個小問題。微軟沒有擁有任何 Linux 技術。它完全依賴於外部的廠家，目前 Canonical 為其提供了完全的 Linux 層。如果 Canonical 被強力的競爭對手收購，那會是一個很大的風險。</p><p>或許對微軟而言嘗試收購 Canonical 是有意義的，並且會將核心技術收入囊中。這是有道理的。</p><h3 id="這對-linux-供應商意味着什麼" tabindex="-1">這對 Linux 供應商意味着什麼 <a class="header-anchor" href="#這對-linux-供應商意味着什麼" aria-label="Permalink to “這對 Linux 供應商意味着什麼”">​</a></h3><p>表面上，很顯然這對微軟是個勝利，因為它的客户可以留存在 Windows 世界中。它還將包含 Linux 在數據中心中的發展勢頭。它或許還會影響 Linux 桌面，由於現在 IT 專家不必為了尋找 *NIX 工具使用 Linux 桌面了，它們可以在 Windows 中做任何事。</p><p>微軟的成功是傳統 Linux 廠家的失敗麼？某種程度上來説，是的，微軟已經成為了一個直接競爭者。但是這裏明顯的贏家是 Linux。</p><hr>',24)),r("p",null,[n[1]||(n[1]=i("via: ",-1)),t(o,{href:"http://www.cio.com/article/3197016/linux/how-microsoft-is-becoming-a-linux-vendor.html"},{default:e(()=>[...n[0]||(n[0]=[i("http://www.cio.com/article/3197016/linux/how-microsoft-is-becoming-a-linux-vendor.html",-1)])]),_:1})]),r("p",null,[n[5]||(n[5]=i("作者：",-1)),t(o,{href:"http://www.cio.com/author/Swapnil-Bhartiya/"},{default:e(()=>[...n[2]||(n[2]=[i("Swapnil Bhartiya",-1)])]),_:1}),n[6]||(n[6]=i(" 譯者：",-1)),t(o,{href:"https://github.com/geekpi"},{default:e(()=>[...n[3]||(n[3]=[i("geekpi",-1)])]),_:1}),n[7]||(n[7]=i(" 校對：",-1)),t(o,{href:"https://github.com/wxy"},{default:e(()=>[...n[4]||(n[4]=[i("wxy",-1)])]),_:1})]),r("p",null,[n[10]||(n[10]=i("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[8]||(n[8]=[i("LCTT",-1)])]),_:1}),n[11]||(n[11]=i(" 原創編譯，",-1)),t(o,{href:"https://linux.cn/"},{default:e(()=>[...n[9]||(n[9]=[i("Linux中國",-1)])]),_:1}),n[12]||(n[12]=i(" 榮譽推出",-1))])])}const b=a(l,[["render",L]]);export{h as __pageData,b as default};
